-- ISS-4965 (Perrin, 2026-10-05): the usage-space digest of a definition revision
-- whose stored `content` was secret-redacted. Usage rows carry the digest of the
-- raw body, which a redacted body can no longer reproduce, so the version-usage
-- and org-population reads prefer this column when it is set. Nullable with no
-- default: every existing row holds the raw body it was observed with, and the
-- reads keep deriving the digest from it. Generated by `prisma migrate diff`.
--
-- The ADD COLUMN is a catalog change under ACCESS EXCLUSIVE on a table the
-- component sync lane writes, so `SET lock_timeout` bounds lock queueing behind
-- a long open transaction, as 20261002161500_iss11212 does.
SET lock_timeout = '5s';

-- AlterTable
ALTER TABLE "agent_component_versions" ADD COLUMN     "usage_scope_hash" TEXT;

RESET lock_timeout;
